/* Independent Write.law explorer. Source records remain attributable to their compiler. */
(()=>{'use strict';
const C=window.ExplorerCore,T=window.ExplorerContent,$=id=>document.getElementById(id),h=C.escape,n=v=>Number(v).toLocaleString('en-US');
const ORIGINAL=JSON.parse($('dataset').textContent),BASE=JSON.parse($('project-config').textContent),KEY='writelaw-explorer-v1:'+location.pathname+(BASE.exportId?':'+BASE.exportId:'');
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(KEY+key))??fallback;}catch{return fallback;}}
function store(key,value){try{localStorage.setItem(KEY+key,JSON.stringify(value));}catch{toast('Browser storage is unavailable. You can still export your work.');}}
let config={...BASE,...readStore(':config',{})},dataset=ORIGINAL,mapping=C.DEFAULT_MAPPING,records=C.normalizeDataset(dataset,mapping);
let ui={route:'overview',f:{},page:1,sort:'new',table:true,cumulative:false,currency:'USD',selected:[],saved:readStore(':saved',[]),onlySaved:false,practice:readStore(':practice',{}),exercise:T.exercises[0].id,group:'Court filings',reviewGroup:'Court filings',review:{},evidence:[{claim:'',source:'',status:'Needs review'}],quoteA:'',quoteB:'',quoteNorm:false,quoteResult:null,pending:null};
let previousFocus=null,lastFocus=null,renderTimer=null;
const ICONS={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',decisions:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',geography:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M3 12h18 M12 3c-5 6-5 12 0 18 M12 3c5 6 5 12 0 18',patterns:'M4 20V10h4v10 M10 20V4h4v16 M16 20V7h4v13',study:'M4 4h7v16H4z M14 4h6v16h-6z M7 8h1 M7 12h1 M17 8h1',practice:'M4 5h6l2 2 2-2h6v14h-6l-2 2-2-2H4z M12 7v14',review:'M5 3h14v18H5z M8 8l1 1 2-3 M13 8h3 M8 15l1 1 2-3 M13 15h3',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',sources:'M8 3H4v18h16V7h-8V3z M8 12h8 M8 16h6'};
const PAGES=[['overview','Findings for educators'],['decisions','Browse decisions'],['geography','Geography'],['patterns','Errors & outcomes'],['study','The 450-order study'],['practice','Practice exercises'],['review','Review tools'],['settings','Customize & import'],['sources','Sources & methods']];
function icon(key){return `<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${ICONS[key]||ICONS.decisions}"/></svg>`;}
function toast(text){const el=$('toast');el.textContent=text;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.hidden=true;},3800);}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const date=v=>v?new Date(v+'T12:00:00Z').toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}):'Date not recorded';
const month=v=>new Date(v+'-01T12:00:00Z').toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});
const opt=(value,label,chosen)=>`<option value="${h(value)}" ${value===chosen?'selected':''}>${h(label)}</option>`;
const options=(key,selected,all)=>opt('',all,selected)+C.count(records,key).map(([v,count])=>opt(v,`${v} (${n(count)})`,selected)).join('');
function money(r){const m=r.money;if(m.status==='missing')return 'Not recorded';if(m.status==='unknown')return 'Amount unknown'+(m.currency?' ('+m.currency+')':'');if(m.status==='known')return n(m.value)+(m.currency?' '+m.currency:' · currency not recorded');return m.raw;}
function filtered(){return C.filterRows(records,{...ui.f,...(ui.onlySaved?{saved:ui.saved}:{})});}
function currentRows(){const out=filtered().slice();if(ui.sort==='title')out.sort((a,b)=>a.title.localeCompare(b.title));else if(ui.sort==='old')out.sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));else out.sort((a,b)=>(b.date||'').localeCompare(a.date||''));return out;}
function activeCount(){return Object.values(ui.f).filter(Boolean).length;}
function syncHash(){const p=new URLSearchParams();Object.entries(ui.f).forEach(([k,v])=>{if(v)p.set(k,String(v));});if(ui.route==='overview'&&ui.findingSection)p.set('section',ui.findingSection);history.replaceState(null,'','#'+ui.route+(p.size?'?'+p:''));}
function fromHash(){const [r,q]=(location.hash.slice(1)||'overview').split('?');ui.route=PAGES.some(([x])=>x===r)?r:'overview';ui.f={};new URLSearchParams(q||'').forEach((v,k)=>{if(['country','actor','type','outcome','tool','field','state','from','to','q'].includes(k))ui.f[k]=v;else if(['money','discipline','excludeAlleged','excludeDisputed'].includes(k))ui.f[k]=v==='true';});ui.page=1;ui.findingSection=new URLSearchParams(q||'').get('section')||'';render();if(ui.route==='overview'&&ui.findingSection)requestAnimationFrame(()=>scrollToFinding(ui.findingSection,false));}
function go(route){ui.findingSection='';ui.route=route;ui.page=1;syncHash();render();document.body.classList.remove('menu-open');window.scrollTo(0,0);}
function setFilter(key,value,route){ui.f[key]=value;ui.page=1;if(route)ui.route=route;syncHash();render();}
function panel(title,description,body,extra=''){return `<section class="panel"><div class="panelhead"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${extra}</div>${body}</section>`;}
function heading(kicker,title,description,extra=''){return `<div class="pagehead"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="lede">${description}</p></div>${extra}</div>`;}
function scope(){return `<section class="scope" aria-label="Shared filters"><span class="scope-label">Showing</span><select aria-label="Jurisdiction" data-filter="country">${options('countries',ui.f.country,'All jurisdictions')}</select><select aria-label="Who used AI" data-filter="actor">${opt('','All participants',ui.f.actor)}${opt('@legal','Lawyers & legal staff',ui.f.actor)}${C.count(records,'actors').map(([v,c])=>opt(v,`${v} (${n(c)})`,ui.f.actor)).join('')}</select><span class="spacer"></span><span class="scope-summary">${n(filtered().length)} of ${n(records.length)} records</span>${activeCount()?`<button class="small quiet" data-action="reset">Clear ${activeCount()} filter${activeCount()===1?'':'s'}</button>`:''}</section>${activeCount()?`<div class="tags" style="margin:-6px 0 20px">${Object.entries(ui.f).filter(([,v])=>v).map(([k,v])=>`<button class="chip" data-action="remove-filter" data-key="${h(k)}">${h(({q:'Search',country:'Jurisdiction',actor:'Participant',type:'Error',outcome:'Outcome',tool:'Tool',field:'Field',state:'State',from:'From',to:'Through',money:'Monetary entries',discipline:'Professional-sanction flag',excludeAlleged:'Exclude alleged',excludeDisputed:'Exclude vendor-disputed'})[k]||k)}${v===true?'':': '+h(v==='@legal'?'Lawyers & legal staff':v)} ×</button>`).join('')}</div>`:''}`;}
function stat(label,value,note){return `<div class="stat"><div class="label">${label}</div><div class="number">${value}</div><div class="note">${note}</div></div>`;}
function bars(entries,key,limit=8,denominator=0){const shown=entries.slice(0,limit),max=Math.max(1,...shown.map(x=>x[1]));return `<div class="barlist">${shown.map(([label,value])=>`<${key?'button':'div'} class="barrow" ${key?`data-action="bar-filter" data-key="${h(key)}" data-value="${h(label)}"`:''}><span class="barlabel"><span>${h(label)}</span><strong>${n(value)}${denominator?` <span class="muted small-text">${value>0&&value/denominator<0.005?'&lt;1':Math.round(value/denominator*100)}%</span>`:''}</strong></span><span class="bartrack"><span class="barfill" style="width:${value/max*100}%"></span></span></${key?'button':'div'}>`).join('')}</div>${entries.length>limit?`<p class="chart-note">Showing the ${limit} largest groups of ${n(entries.length)}. Use the filters to explore the others.</p>`:''}`;}
function timeline(rows){const s=C.series(rows);if(!s.length)return `<div class="empty">There are no dated records in this selection.</div>`;const w=800,H=270,left=48,right=15,top=20,bottom=45,plot=w-left-right,height=H-top-bottom,max=Math.max(1,...s.map(d=>ui.cumulative?d.total:d.count)),step=plot/s.length;let svg=`<svg id="timeline-svg" viewBox="0 0 ${w} ${H}" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">${ui.cumulative?'Cumulative records':'Records per month'}</title><desc id="chart-desc">Counts based on decision dates. The last month may be incomplete. A data table follows the chart.</desc>`;for(let i=0;i<=4;i++){const v=max*i/4,y=top+height-height*i/4;svg+=`<line x1="${left}" x2="${w-right}" y1="${y}" y2="${y}" stroke="var(--line)"/><text x="${left-10}" y="${y+4}" text-anchor="end" font-size="11" fill="var(--muted)">${n(Math.round(v))}</text>`;}
if(ui.cumulative){const points=s.map((d,i)=>`${left+step*(i+.5)},${top+height-(d.total/max)*height}`).join(' ');svg+=`<polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="3"/>`;}
s.forEach((d,i)=>{const v=ui.cumulative?d.total:d.count,x=left+step*i,y=top+height-v/max*height;svg+=`<g class="chart-mark" tabindex="0" role="button" data-action="month-filter" data-month="${d.month}" aria-label="${h(month(d.month))}: ${n(v)} records. Open decisions."><title>${month(d.month)}: ${n(v)} ${ui.cumulative?'cumulative records':'records'}</title>${ui.cumulative?`<circle cx="${x+step/2}" cy="${y}" r="3.5" fill="var(--accent)"/><rect x="${x}" y="${top}" width="${step}" height="${height}" fill="transparent"/>`:`<rect x="${x+Math.min(2,step*.12)}" y="${y}" width="${Math.max(1,step-4)}" height="${Math.max(0,top+height-y)}" rx="2" fill="var(--accent)" opacity="${d.month===dataset.meta.snapshot?.slice(0,7)?'.45':'.86'}"/>`}</g>`;if(i%Math.max(1,Math.ceil(s.length/8))===0||i===s.length-1)svg+=`<text x="${x+step/2}" y="${H-14}" text-anchor="middle" fill="var(--muted)" font-size="10">${month(d.month)}</text>`;});svg+='</svg>';return `<div class="chart">${svg}</div><div class="actions"><button class="small" data-action="chart-export">Export chart SVG</button><button class="small" data-action="chart-data">Export monthly CSV</button></div><p class="chart-note">Counts use the dates in the source, not the dates records were added. The latest month may be incomplete. Select a bar or point to open its records.</p><details class="accordion"><summary>Read the chart as a table</summary><div class="table-wrap"><table><thead><tr><th>Month</th><th>Decisions</th><th>Cumulative</th></tr></thead><tbody>${s.map(d=>`<tr><td>${month(d.month)}</td><td>${n(d.count)}</td><td>${n(d.total)}</td></tr>`).join('')}</tbody></table></div></details>`;}
function caseFlags(r){return `${r.alleged?'<span class="badge warn">AI use alleged</span>':''}${r.disputed?'<span class="badge warn">Vendor disputed</span>':''}`;}
function caseLink(r){return `<button class="link-button case-title" data-action="case" data-id="${r.id}">${h(r.title)}</button>`;}
function miniCases(rows,limit=4){return rows.slice(0,limit).map(r=>`<article class="insight"><div class="kicker">${date(r.date)} · ${h(r.countries.join(', ')||'Jurisdiction not recorded')}</div><h3>${caseLink(r)}</h3><p>${h(r.court||'Court not recorded')} · ${h(r.actors.join(', ')||'Participant not recorded')}</p><div class="tags">${r.types.slice(0,2).map(x=>`<span class="badge">${h(x)}</span>`).join('')}${caseFlags(r)}</div></article>`).join('');}
function overview(){return findings();}
/*__FINDINGS__*/
function filterInput(id,label,key,type='text'){return `<label>${label}<input id="${id}" type="${type}" data-filter="${key}" value="${h(ui.f[key]||'')}" ${type==='search'?'placeholder="Case, court, passage, tool, or topic"':''}></label>`;}
function decisions(){const rows=currentRows(),size=25,pages=Math.max(1,Math.ceil(rows.length/size));ui.page=Math.min(ui.page,pages);const list=rows.slice((ui.page-1)*size,ui.page*size);return heading('Decision-level records','Browse the decisions','Search the source descriptions, narrow the records, and open a decision to see its context and source. Filters carry across the charts.')+scope()+`<section class="panel"><div class="filters">${filterInput('case-search','Search all record text','q','search')}<label>Error type<select data-filter="type">${options('types',ui.f.type,'All error types')}</select></label><label>AI tool as recorded<select data-filter="tool">${options('tool',ui.f.tool,'All tools and unknowns')}</select></label></div><details class="accordion" ${['from','to','outcome','field','state','money','discipline','excludeAlleged','excludeDisputed'].some(k=>ui.f[k])?'open':''}><summary>Dates, outcomes, and other filters</summary><div class="advanced">${filterInput('date-from','From date','from','date')}${filterInput('date-to','Through date','to','date')}<label>Outcome label<select data-filter="outcome">${options('outcomes',ui.f.outcome,'All recorded outcomes')}</select></label><label>Legal field<select data-filter="field">${options('fields',ui.f.field,'All fields')}</select></label><label>U.S. state or D.C.<select data-filter="state">${opt('','Any / unassigned',ui.f.state)}${Object.entries(C.STATES).sort((a,b)=>a[1].localeCompare(b[1])).map(([v,l])=>opt(v,l,ui.f.state)).join('')}</select></label><label class="check"><input type="checkbox" data-filter="money" ${ui.f.money?'checked':''}> Monetary entry recorded</label><label class="check"><input type="checkbox" data-filter="discipline" ${ui.f.discipline?'checked':''}> Professional-sanction flag</label><label class="check"><input type="checkbox" data-filter="excludeAlleged" ${ui.f.excludeAlleged?'checked':''}> Exclude alleged AI use</label><label class="check"><input type="checkbox" data-filter="excludeDisputed" ${ui.f.excludeDisputed?'checked':''}> Exclude vendor-disputed records</label></div><p class="formhelp">The professional-sanction flag is the source’s classification; it does not establish a final disciplinary finding. Outcome labels are not independently recoded.</p></details></section><div class="toolbar"><div class="left"><strong class="results-meta">${n(rows.length)} records</strong><label class="check"><input type="checkbox" id="only-saved" ${ui.onlySaved?'checked':''}>Saved (${ui.saved.length})</label></div><div class="right"><select aria-label="Sort records" id="sort-records">${opt('new','Newest first',ui.sort)}${opt('old','Oldest first',ui.sort)}${opt('title','Case name',ui.sort)}</select><button class="small" data-action="view">${ui.table?'Card view':'Table view'}</button><button class="small" data-action="export-csv">Export CSV</button><button class="small" data-action="export-json">Export JSON</button></div></div>${!list.length?`<div class="empty"><h2>No records match these filters.</h2><p>Try removing one filter or broadening your search.</p><button data-action="reset">Clear filters</button></div>`:ui.table?`<div class="table-wrap"><table><thead><tr><th><span class="visually-hidden">Compare</span></th><th style="width:38%">Decision</th><th>Date</th><th>Participant</th><th>Outcome / monetary entry</th><th>Saved</th></tr></thead><tbody>${list.map(r=>`<tr><td><input type="checkbox" aria-label="Compare ${h(r.title)}" data-compare="${r.id}" ${ui.selected.includes(r.id)?'checked':''}></td><td>${caseLink(r)}<div class="case-court">${h(r.court)} · ${h(r.countries.join(', '))}</div><div class="tags">${caseFlags(r)}</div></td><td class="nowrap">${date(r.date)}</td><td>${h(r.actors.join(', ')||'Not recorded')}</td><td><div>${h(r.outcome.length>110?r.outcome.slice(0,110)+'…':r.outcome||'Not recorded')}</div><div class="case-court">${h(money(r))}</div></td><td><button class="small quiet" data-action="save" data-id="${r.id}" aria-label="${ui.saved.includes(r.id)?'Unsave':'Save'} ${h(r.title)}">${ui.saved.includes(r.id)?'★':'☆'}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="case-cards">${list.map(r=>`<article class="case-card"><header><span>${date(r.date)}</span><button class="small quiet" data-action="save" data-id="${r.id}">${ui.saved.includes(r.id)?'★ Saved':'☆ Save'}</button></header><h3>${caseLink(r)}</h3><p>${h(r.court)} · ${h(r.countries.join(', '))}</p><p>${h(r.outcome||'Outcome not recorded')}</p><div class="tags">${r.types.map(x=>`<span class="badge">${h(x)}</span>`).join('')}${caseFlags(r)}</div><footer><span>${h(money(r))}</span><label class="check"><input type="checkbox" data-compare="${r.id}" ${ui.selected.includes(r.id)?'checked':''}> Compare</label></footer></article>`).join('')}</div>`}<div class="pagination"><span>Page ${ui.page} of ${pages}${rows.length?` · ${n((ui.page-1)*size+1)}–${n(Math.min(ui.page*size,rows.length))} of ${n(rows.length)}`:''}</span><div class="buttons"><button class="small" data-action="page" data-delta="-1" ${ui.page===1?'disabled':''}>← Previous</button><button class="small" data-action="page" data-delta="1" ${ui.page>=pages?'disabled':''}>Next →</button></div></div>${ui.selected.length?`<div class="comparebar"><span>${ui.selected.length} selected for comparison</span><button class="small" data-action="compare" ${ui.selected.length<2?'disabled':''}>Compare decisions</button><button class="small" data-action="clear-compare">Clear</button></div>`:''}`;}
const TILE={AK:[1,1],ME:[1,12],VT:[2,10],NH:[2,11],WA:[3,1],ID:[3,2],MT:[3,3],ND:[3,4],MN:[3,5],WI:[3,6],MI:[3,8],NY:[3,10],MA:[3,11],RI:[3,12],OR:[4,1],NV:[4,2],WY:[4,3],SD:[4,4],IA:[4,5],IL:[4,6],IN:[4,7],OH:[4,8],PA:[4,9],NJ:[4,10],CT:[4,11],CA:[5,1],UT:[5,2],CO:[5,3],NE:[5,4],MO:[5,5],KY:[5,6],WV:[5,7],VA:[5,8],MD:[5,9],DE:[5,10],AZ:[6,2],NM:[6,3],KS:[6,4],AR:[6,5],TN:[6,6],NC:[6,7],SC:[6,8],DC:[6,9],OK:[7,4],LA:[7,5],MS:[7,6],AL:[7,7],GA:[7,8],HI:[8,1],TX:[8,4],FL:[8,9]};
function geography(){const rows=filtered(),us=rows.filter(r=>r.countries.includes('USA')),counts=Object.fromEntries(C.count(us,'state')),max=Math.max(1,...Object.values(counts)),unknown=us.filter(r=>!r.state).length;return heading('Locations in the source','Where the decisions were issued','Compare jurisdictions or select a U.S. state to read its records. Locations refer to courts, not the lawyers’ home states.')+scope()+`<div class="grid2">${panel('United States','An equal-sized tile for each state and the District of Columbia.',`<div class="map-grid">${Object.entries(TILE).map(([code,[row,col]])=>{const v=counts[code]||0;return `<button class="map-tile ${ui.f.state===code?'selected':''}" style="grid-row:${row};grid-column:${col};background:color-mix(in srgb,var(--accent) ${v?12+Math.round(v/max*60):0}%,var(--surface));color:${v/max>.6?'#fff':'var(--ink)'}" title="${h(C.STATES[code])}: ${v} records" aria-label="${h(C.STATES[code])}, ${v} records" data-action="map-state" data-value="${code}"><strong>${code}</strong><span>${n(v)}</span></button>`;}).join('')}</div><p class="chart-note">${n(unknown)} U.S. records are not assigned to a state. State assignments are inferred only when the court label names the state or D.C.; nationwide courts and most federal appellate courts remain unassigned. This is a tile map, not a geographic boundary map.</p><details class="accordion"><summary>State counts as a table</summary><div class="table-wrap"><table><thead><tr><th>State / district</th><th>Records</th></tr></thead><tbody>${Object.entries(C.STATES).sort((a,b)=>a[1].localeCompare(b[1])).map(([c,label])=>`<tr><td>${h(label)}</td><td>${n(counts[c]||0)}</td></tr>`).join('')}</tbody></table></div></details>`)}${panel('Jurisdictions','The source can attach more than one jurisdiction to a record.',bars(C.count(rows,'countries'),'country',12))}</div>${panel('Courts with the most records in this selection','Court labels are preserved rather than merged into an inferred hierarchy.',bars(C.count(rows,'court'),null,16),`<button class="small" data-action="go" data-route="decisions">Search courts</button>`)}`;}
function patterns(){const rows=filtered(),values=rows.filter(r=>r.money.status==='known'&&r.money.currency===ui.currency),med=C.median(values.map(r=>r.money.value)),currencies=[...new Set(records.map(r=>r.money.currency).filter(Boolean))].sort(),unknown=rows.filter(r=>r.money.status==='unknown').length;const ranges=[['Under 1,000',v=>v<1000],['1,000–4,999',v=>v>=1000&&v<5000],['5,000–9,999',v=>v>=5000&&v<10000],['10,000–24,999',v=>v>=10000&&v<25000],['25,000 or more',v=>v>=25000]].map(([l,test])=>[l,values.filter(r=>test(r.money.value)).length]);return heading('Compare what the records describe','Errors and court responses','These views use the database’s labels. They do not independently determine whether AI caused an error or whether a court imposed a final sanction.')+scope()+`<div class="grid2 equal">${panel('Types of error','Each type is counted at most once per decision; types can overlap.',bars(C.count(rows,'types'),'type',10))}${panel('Recorded outcome labels','Wording varies. Similar labels have not been silently combined.',bars(C.count(rows,r=>r.outcomes.map(x=>x.toLowerCase())),'outcome',10))}</div><div class="grid2 equal">${panel('Named and unnamed tools','“Implied” and “Unidentified” are source labels, not products.',bars(C.count(rows,'tool'),'tool',10))}${panel('Legal fields','A decision may be classified in more than one field.',bars(C.count(rows,'fields'),'field',10))}</div><div class="section-title"><div><div class="eyebrow">Monetary entries</div><h2>Amounts with a known figure and currency</h2></div><label>Currency<select id="currency">${currencies.map(c=>opt(c,c,ui.currency)).join('')}</select></label></div><div class="stats">${stat('Known amounts',n(values.length),h(ui.currency)+' entries in the current selection.')}${stat('Median amount',med===null?'—':n(med),'A descriptive figure, not a typical fine.')}${stat('Unknown amounts',n(unknown),'The source uses 1 as a placeholder for an unknown figure.')}${stat('Professional-sanction flag',n(rows.filter(r=>r.discipline).length),'The source flag does not establish a final discipline result.')}</div><div class="grid2 equal">${panel('Distribution · '+h(ui.currency),'Only known figures in this currency are included.',bars(ranges,null,6))}<div class="callout warn"><h3>A monetary entry is not necessarily a fine.</h3><p>The field can reflect fines, fee awards, or other monetary consequences. Different currencies are never added together. Blank entries, unknown amounts, and amounts without a currency are excluded from this distribution.</p><p>The figures are transcribed from the dataset and have not been independently checked against each order.</p></div></div>`;}
function study(){const s=T.study;return heading('A separate, fixed study','What 450 U.S. orders can tell us','This supplemental analysis examines 450 U.S. lawyer-related orders. Its published findings are separate from the decision-level database used elsewhere in this explorer.')+`<div class="callout warn"><h3>These figures do not change with the filters.</h3><p>This is a ${h(s.date)} study snapshot with a denominator of 450 orders. The categories were coded in a single AI-assisted pass, without a second coder or an intercoder-reliability measure. Person-level workbooks were not made public; this version does not recreate them.</p><button class="small" data-action="go" data-route="${s.methodRoute}">Read the study methods</button></div><div class="stats">${stat('Orders coded','450','U.S. orders involving lawyers in the original study.')}${stat('No invented case','128','An error need not involve a nonexistent case.')}${stat('Named AI tool','86','Most orders did not identify a particular product.')}${stat('No listed response yet','124','A study classification, not a finding of no consequences.')}</div><div class="grid2 equal">${panel('Who identified the problem','Categories published by the original study.',bars(s.detection,null,6,450))}${panel('Selected court responses','More than one response can appear in an order.',bars(s.responses,null,12,450))}</div><div class="grid2 equal"><article class="insight"><div class="kicker">Using the findings</div><h3>Check more than whether a case exists.</h3><p>The study’s categories distinguish invented sources from other problems, including misstatements and quotations. For teaching, that is a useful reason to ask students what an authority supports, not just whether they can retrieve it.</p></article><article class="insight"><div class="kicker">Reading the limits</div><h3>The sample cannot establish who is most likely to make an error.</h3><p>Counts of lawyers, firms, or products within recorded problem cases need a relevant comparison population before they can support a risk comparison. These descriptive findings do not supply that denominator.</p></article></div><p class="muted">The educator overview brings the experience, practice-setting, court, workflow, and response findings together on one page. Each analysis retains its own date and sample size.</p>`;}
function practice(){const list=T.exercises.filter(x=>x.group===ui.group),e=list.find(x=>x.id===ui.exercise)||list[0];ui.exercise=e.id;const answer=ui.practice[e.id];const done=T.exercises.filter(x=>ui.practice[x.id]?.revealed).length;return heading('Original teaching exercises','Practice reviewing AI-assisted work','Read the supplied material, decide what needs attention, and compare your reasoning with the explanation. All scenarios and source passages here are fictional.')+`<div class="toolbar"><div class="left tabs">${['Court filings','Contracts'].map(g=>`<button class="${g===ui.group?'active':''}" data-action="practice-group" data-group="${g}">${g}</button>`).join('')}</div><div class="right"><span>${done} of ${T.exercises.length} reviewed</span><button class="small" data-action="practice-export">Export exercises & answer key</button><button class="small quiet" data-action="practice-reset">Reset progress</button></div></div><div class="exercise-layout"><div class="exercise-nav" aria-label="Choose an exercise">${list.map((x,i)=>`<button class="${x.id===e.id?'active':''}" data-action="exercise" data-id="${x.id}"><span class="exercise-number">${ui.practice[x.id]?.revealed?'✓':i+1}</span><span>${h(x.title)}</span></button>`).join('')}</div><section class="panel"><div class="eyebrow">${h(e.skill)} · Fictional exercise</div><h2>${h(e.title)}</h2><div class="sourcebox"><div class="eyebrow">Supplied source or instructions</div>${h(e.source)}</div><div class="sourcebox"><div class="eyebrow">Draft to review</div>${h(e.draft)}</div><h3>${h(e.question)}</h3><fieldset class="choices" style="border:0;padding:0;margin:0"><legend class="visually-hidden">Choose a response</legend>${e.choices.map((x,i)=>`<label class="choice"><input type="radio" name="exercise-answer" value="${i}" ${answer?.choice===i?'checked':''}><span>${h(x)}</span></label>`).join('')}</fieldset><button class="primary" data-action="reveal" data-id="${e.id}">Compare your reasoning</button>${answer?.revealed?`<div class="answer"><div class="eyebrow">${answer.choice===e.correct?'Your choice addresses the central issue':'Another choice addresses the central issue more directly'}</div><h3>${h(e.choices[e.correct])}</h3><p>${h(e.explanation)}</p><h4>A possible repair or next step</h4><p>${h(e.repair)}</p><h4>For discussion</h4><p>${h(e.discussion)}</p></div>`:''}</section></div><p class="chart-note">Progress is saved in this browser. These are new exercises for this version, not copies of the original project’s filed passages or training modules. They are educational examples, not jurisdiction-specific advice or accredited CLE.</p>`;}
function review(){const checks=T.checklists[ui.reviewGroup],done=checks.filter((_,i)=>ui.review[ui.reviewGroup+':'+i]).length;return heading('Tools that run in this browser','Review the work against its sources','Compare passages, keep track of open questions, and record the checks you performed. Pasted text and review notes are held in memory and are not sent to a server or saved automatically.')+`<section class="panel"><div class="panelhead"><div><h2>Compare a quotation with its source</h2><p>This compares text, not meaning, authority, or legal sufficiency.</p></div><button class="small" data-action="quote-example">Try an example</button></div><div class="formgrid"><label>Original source<textarea id="quote-a" rows="5" maxlength="20000" placeholder="Paste the source passage.">${h(ui.quoteA)}</textarea></label><label>Draft quotation<textarea id="quote-b" rows="5" maxlength="20000" placeholder="Paste the draft passage.">${h(ui.quoteB)}</textarea></label></div><div class="toolbar"><label class="check"><input id="quote-normalize" type="checkbox" ${ui.quoteNorm?'checked':''}>Ignore differences in whitespace</label><div class="right"><button class="small quiet" data-action="quote-clear">Clear text</button><button class="primary" data-action="quote-compare">Compare text</button></div></div><div id="quote-results">${quoteOutput()}</div><p class="formhelp">Up to 20,000 characters per passage. Red marks text removed from the source; green marks added text. A matching passage can still be misleading when used out of context.</p></section><div class="grid2 equal"><section class="panel"><div class="panelhead"><div><h2>Review checklist</h2><p>Use this as a starting point and add the checks your matter needs.</p></div><select aria-label="Checklist type" id="review-group">${['Court filings','Contracts'].map(g=>opt(g,g,ui.reviewGroup)).join('')}</select></div><div class="progress"><div style="width:${done/checks.length*100}%"></div></div><p class="muted">${done} of ${checks.length} checks marked complete</p><div class="checklist">${checks.map(([label,text],i)=>`<label class="check-item"><input type="checkbox" data-review="${i}" ${ui.review[ui.reviewGroup+':'+i]?'checked':''}><span><strong>${h(label)}</strong><br>${h(text)}</span></label>`).join('')}</div><label>Reviewer and matter label<input id="reviewer" value="${h(ui.reviewer||'')}" placeholder="Use a nonconfidential reference."></label><div class="actions"><button class="small" data-action="review-export">Export review record</button><button class="small quiet" data-action="review-clear">Clear checklist</button></div></section><section class="panel"><div class="panelhead"><div><h2>Questions and supporting sources</h2><p>Record what needs checking and where you found support.</p></div></div><div id="evidence-rows">${ui.evidence.map((e,i)=>`<div class="evidence-row"><label>Claim or question<textarea rows="2" data-evidence="${i}" data-field="claim">${h(e.claim)}</textarea></label><label>Source or location<textarea rows="2" data-evidence="${i}" data-field="source">${h(e.source)}</textarea></label><label>Status<select data-evidence="${i}" data-field="status">${['Needs review','Supported','Needs revision','Unresolved'].map(s=>opt(s,s,e.status)).join('')}</select></label><button class="small quiet" data-action="evidence-remove" data-index="${i}" aria-label="Remove question ${i+1}">×</button></div>`).join('')}</div><div class="actions"><button class="small" data-action="evidence-add">Add a question</button><button class="small" data-action="evidence-export">Export CSV</button></div><p class="formhelp">Export any notes you need to keep before closing or reloading the page.</p></section></div>`;}
function quoteOutput(){const q=ui.quoteResult;if(!q)return '';return `<div class="callout ${q.equal?'':'warn'}"><strong>${q.equal?'The passages match'+(ui.quoteNorm?' after normalizing whitespace':' exactly')+'.':'The passages differ.'}</strong>${q.limited?'<p>This passage is long; the display shows the complete old and new versions rather than a word-by-word alignment.</p>':''}</div><div class="diffview">${q.parts.map(p=>p.kind==='same'?h(p.text):`<${p.kind}>${h(p.text)}</${p.kind}>`).join('')}</div>`;}
function settings(){return heading('Make this project your own','Customize the explorer','Change the presentation, bring in another dataset, or export a portable copy. Your changes here do not modify the public source database or other visitors’ copies.')+`<div class="settings-layout"><section class="panel"><div class="panelhead"><div><h2>Project settings</h2><p>Saved in this browser. Export a portable copy to keep the settings with the data.</p></div></div><form id="settings-form"><div class="formgrid"><label class="full">Project name<input name="name" maxlength="90" value="${h(config.name)}" required></label><label>Organization or author<input name="organization" maxlength="80" value="${h(config.organization)}"></label><label>Accent color<input name="accent" type="color" value="${/^#[0-9a-f]{6}$/i.test(config.accent)?config.accent:'#217963'}"></label><label class="full">Introductory text<textarea name="intro" rows="4" maxlength="1500">${h(config.intro)}</textarea></label><label>Appearance<select name="theme">${opt('paper','Warm paper',config.theme)}${opt('white','White',config.theme)}${opt('slate','Soft blue',config.theme)}</select></label><div><label class="check"><input type="checkbox" name="study" ${config.study?'checked':''}>Show the additional study findings</label><label class="check"><input type="checkbox" name="practice" ${config.practice?'checked':''}>Show legal practice exercises</label></div></div><div class="actions"><button type="submit" class="primary">Save settings</button><button type="button" class="quiet" data-action="settings-reset">Restore default settings</button></div></form></section><section class="panel"><div class="panelhead"><div><h2>Export your version</h2><p>Choose a complete working copy or a data file for further editing.</p></div></div><p>A portable HTML copy includes the current dataset, settings, charts, and tools. It opens without a server or an internet connection; source links still need internet access.</p><div class="actions"><button class="primary" data-action="portable">Export portable website</button><button data-action="project-export">Export project JSON</button><button data-action="raw-export">Export source CSV</button></div><p class="formhelp">Exports do not include pasted comparison text, review notes, saved-case selections, or exercise progress. Keep your own copy of any notes you need.</p><div class="callout"><h3>Publishing changes</h3><p>Browser settings affect your copy only. A public update requires replacing the published file. The editable project separates its data, copy, styling, and application code for that purpose.</p></div></section></div><section class="panel"><div class="panelhead"><div><h2>Use another dataset</h2><p>Import a CSV with a header row, a JSON array of records, or a project JSON exported from this app.</p></div></div><div class="upload"><label>Choose a CSV or JSON file<input type="file" id="import-file" accept=".csv,.json,text/csv,application/json"></label><p class="formhelp">The file is read locally. It is not uploaded, and imported records are not saved automatically. Limit: 25 MB and 50,000 rows. Map date fields as YYYY-MM-DD; multi-value categories may be separated with semicolons.</p></div>${ui.pending?importPreview():''}<div class="actions"><button class="small" data-action="restore-source">Restore the included Charlotin snapshot</button></div></section>`;}
function importPreview(){const p=ui.pending,keys=p.dataset.columns||Object.keys(p.dataset.rows[0]||{});return `<div class="section-space"><h3>Review the column mapping</h3><p>${n(p.dataset.rows.length)} rows · ${keys.length} columns. A title is required. Unmapped fields remain unknown.</p><form id="import-form"><div class="formgrid"><label>Dataset name<input name="datasetName" value="${h(p.dataset.meta?.name||p.filename||'Imported dataset')}" required></label><label>Source author / attribution<input name="author" value="${h(p.dataset.meta?.author||'')}" placeholder="Who compiled these records?"></label><label>Source website<input type="url" name="source" value="${h(p.dataset.meta?.source||'')}" placeholder="https://…"></label><label>Snapshot date<input type="date" name="snapshot" value="${h(C.validDate(p.dataset.meta?.snapshot)||'')}"></label><label>Reuse license / permission note<input name="license" value="${h(p.dataset.meta?.license||'Not specified')}" required></label><label class="check"><input name="sentinel" type="checkbox" ${p.dataset.meta?.oneIsUnknown===true?'checked':''}>A monetary value of 1 means unknown in this dataset</label></div><div class="mapping">${Object.keys(C.DEFAULT_MAPPING).map(k=>`<label>${h(({title:'Record title (required)',court:'Court / organization',countries:'Jurisdictions',date:'Decision / record date',actors:'Participants',tool:'Tool / product',items:'Error type | description',outcome:'Outcome',money:'Amount and currency',discipline:'Professional-sanction flag',alleged:'Alleged flag',disputed:'Disputed flag',disputeNote:'Dispute explanation',pointer:'Source pinpoint',source:'Source URL',details:'Details',field:'Primary field',field2:'Secondary field',state:'U.S. state abbreviation'})[k])}<select name="map-${k}" ${k==='title'?'required':''}>${opt('','Not mapped',p.mapping[k])}${keys.map(col=>opt(col,col,p.mapping[k])).join('')}</select></label>`).join('')}</div><p class="formhelp">This import replaces the active dataset, not the original file. Missing or invalid dates are excluded from time charts, not guessed. Amounts need their currency code, such as “1500 USD,” for currency-specific charts.</p><div class="actions"><button class="primary" type="submit">Use this dataset</button><button type="button" class="quiet" data-action="cancel-import">Cancel import</button></div></form></div>`;}
function sources(){const m=dataset.meta;return heading('Provenance and interpretation','Sources and methods','The charts are only as useful as the records behind them. This page explains what is included, how the data are handled, and where to check the underlying material.')+`<div class="grid2 equal">${panel('Active dataset','',`<dl class="detail-grid"><div class="full"><dt>Dataset</dt><dd>${h(m.name||'Imported dataset')}</dd></div><div><dt>Compiled by</dt><dd>${h(m.author||'Not specified')}</dd></div><div><dt>Snapshot</dt><dd>${date(m.snapshot)}</dd></div><div><dt>Records included</dt><dd>${n(records.length)}</dd></div><div><dt>Reuse terms</dt><dd>${h(m.license||'Not specified')}</dd></div><div class="full"><dt>Source</dt><dd>${C.safeURL(m.source)?`<a href="${h(C.safeURL(m.source))}" target="_blank" rel="noopener noreferrer">${h(m.source)} ↗</a>`:'No source website supplied'}</dd></div></dl><p>${h(m.note||'Imported records have not been independently verified.')}</p>${m.sha256?`<details class="accordion"><summary>Snapshot fingerprint</summary><p class="detail-text">SHA-256 of the original downloaded CSV: <code style="overflow-wrap:anywhere">${h(m.sha256)}</code></p></details>`:''}`)}${panel('This independent version','',`<p>Built for Write.law as a customizable research and teaching tool. The interface, application code, explanations, and fictional exercises were written for this version.</p><p>Case records come from Damien Charlotin’s AI Hallucination Cases Database. The experience, firm-size, source-pronoun, and detailed court findings are supplemental analyses with their own dates and sample sizes. They are not fields in the current case-data export, and the underlying person-level workbooks are not included.</p><p>The default case data are attributed to <strong>AI Hallucination Cases Database, Damien Charlotin</strong>, under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. This version changes the organization and presentation and adds derived groupings. This version does not imply endorsement by the database compiler.</p>` )}</div><section class="panel prose"><h2>How to read the charts</h2><h3>Records are decisions, not unique people or incidents.</h3><p>Several records can concern the same dispute or lawyer. The database contains different kinds of participants and court responses; it is not a list of lawyers who have all received sanctions. Counts should not be described as the number of sanctioned lawyers.</p><h3>Known cases do not provide an error rate.</h3><p>The dataset has no count of all AI uses, all filings, or all lawyers using AI. It cannot establish the prevalence of error or compare product reliability. An increase in records may have several explanations, including changes in reporting and detection.</p><h3>Unknown and disputed information stays visible.</h3><p>Blank entries are shown as not recorded. The alleged-AI-use and vendor-disputed flags are retained, and the record view includes any dispute explanation supplied. “Implied” or “Unidentified” in the AI-tool field does not identify a product. Source descriptions are not rewritten as independent findings.</p><h3>Money is handled conservatively.</h3><p>In the included source, a monetary value of 1 is a placeholder for an unknown figure. Those entries are shown as unknown, not one-dollar penalties. Missing figures and unknown currencies are not treated as zero. Distributions and medians include only parseable known amounts within a single currency. The monetary field can include different kinds of consequences, including fees, and is not relabeled as a fine.</p><h3>Categories can overlap.</h3><p>A record may identify several jurisdictions, participants, errors, or outcomes. Each label is counted once per record, but category totals can exceed the number of records. Repeated source items within a record do not inflate the category count. Most source wording is retained; the misspelled participant label “Governement Lawyer” is displayed as “Government Lawyer,” and case differences are combined in the outcome chart.</p><h3>The U.S. map uses a limited inference.</h3><p>The CSV’s “State(s)” column identifies countries or jurisdictions, not U.S. states. This version infers a U.S. state only from a court label that spells out that state, or a D.C. label. Other courts remain unassigned rather than being mapped to an invented location. Imported explicit state assignments take precedence.</p><h3>The time chart is a snapshot.</h3><p>The chart uses the date supplied with each record. It fills intervening months with zero but does not invent dates for undated records. The most recent month can be incomplete. No scheduled refresh or live connection is enabled in this version; importing or rebuilding with a new source file updates the snapshot.</p><h3>Check the source before relying on a record.</h3><p>Source links and source descriptions are provided to support review. The implementation has been checked for data handling and interface behavior, but the underlying opinions have not all been independently verified. For professional use, read the relevant order, check its status, and confirm the applicable rules.</p></section><section class="panel prose"><h2>Privacy and portability</h2><p>The explorer makes no background requests and uses no analytics or account login. Dataset filtering and imports happen in the browser. Settings, saved-record identifiers for the included dataset, and exercise progress may be stored locally. Pasted source text, reviewer names, and evidence notes stay in memory unless you export them.</p><p>A portable export contains the dataset and project settings, not your working notes or exercise answers. Local browser storage is not a secure document repository. Avoid placing confidential material in exported files or public deployments.</p><div class="actions"><button data-action="portable">Export this website</button><button data-action="raw-export">Export the active source CSV</button></div></section>`;}
function render(){const active=document.activeElement,keep=active?.id,pos=active?.selectionStart;document.documentElement.style.setProperty('--accent',/^#[0-9a-f]{6}$/i.test(config.accent)?config.accent:'#217963');const themes={paper:['#f5f5f0','#fff'],white:['#fafbfc','#fff'],slate:['#f0f3f6','#fff']};const theme=themes[config.theme]||themes.paper;document.documentElement.style.setProperty('--bg',theme[0]);document.documentElement.style.setProperty('--surface',theme[1]);document.title=config.name+' · '+config.organization;
$('sidebar').innerHTML=`<a href="#overview" class="brand"><span class="brandmark">W.</span><span>${h(config.organization||'Research')}<small>${h(config.name)}</small></span></a><div class="nav-label">Read and explore</div><nav aria-label="Primary">${PAGES.filter(([r])=>!['geography','patterns','study'].includes(r)&&(r!=='practice'||config.practice)).map(([r,label])=>`${r==='practice'?'<div class="nav-label">Teaching tools</div>':''}${r==='settings'?'<div class="nav-label">Your project</div>':''}<a href="#${r}" class="${ui.route===r?'active':''}" ${ui.route===r?'aria-current="page"':''}>${icon(r)}<span>${label}</span></a>`).join('')}</nav><details class="advanced-nav" ${['geography','patterns','study'].includes(ui.route)?'open':''}><summary>Additional data views</summary><nav aria-label="Additional data views">${PAGES.filter(([r])=>['geography','patterns','study'].includes(r)&&(r!=='study'||config.study)).map(([r,label])=>`<a href="#${r}" class="${ui.route===r?'active':''}">${icon(r)}<span>${label}</span></a>`).join('')}</nav></details><div class="sidebar-foot"><span class="source-dot"></span> ${n(records.length)} source records<br><span class="small-text">Snapshot: ${date(dataset.meta.snapshot)}</span><br><button class="link-button small-text" data-action="go" data-route="sources">Read the source notes</button></div>`;
$('topbar').innerHTML=`<button class="mobile-menu quiet" data-action="menu" aria-label="Toggle navigation" aria-expanded="${document.body.classList.contains('menu-open')}">☰</button><div class="breadcrumb"><span class="crumb-project">${h(config.name)}</span><span>/</span><strong>${h(PAGES.find(([r])=>r===ui.route)?.[1]||'Overview')}</strong></div><div class="top-actions"><button class="small quiet desktop-button" data-action="search">Search <kbd>⌘ K</kbd></button><button class="small quiet desktop-button" data-action="presentation">Present</button><button class="small" data-action="share">Copy view link</button></div>`;
const views={overview,decisions,geography,patterns,study,practice,review,settings,sources};try{$('main').innerHTML=views[ui.route]();}catch(err){console.error(err);$('main').innerHTML=`<div class="empty"><h1>This view could not be rendered.</h1><p>${h(err.message)}</p><button data-action="reset">Clear filters</button></div>`;}
$('footer').innerHTML=`<span>${h(config.organization)} · Independent research explorer</span><span>${h(dataset.meta.author||'Source author not specified')} · ${h(dataset.meta.license||'Reuse terms not specified')} · <a href="#sources">Sources & limitations</a></span>`;
if(keep&&$(keep)){try{$(keep).focus({preventScroll:true});if(typeof pos==='number')$(keep).setSelectionRange(pos,pos);}catch{}}
}
function closeModal(){const root=$('modal-root');root.innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function modal(title,body,footer='',wide=false){lastFocus=document.activeElement;$('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${h(title)}</h2><button class="quiet" data-action="close-modal" aria-label="Close dialog">×</button></div>${body}${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';$('modal-root').querySelector('button, a, input')?.focus();}
function caseDetail(r){const items=r.items.split(/\s*\|\|\s*/).filter(Boolean);return `<div class="tags">${caseFlags(r)}${r.types.map(x=>`<span class="badge">${h(x)}</span>`).join('')}</div><dl class="detail-grid"><div><dt>Date</dt><dd>${date(r.date)}</dd></div><div><dt>Jurisdiction</dt><dd>${h(r.countries.join(', ')||'Not recorded')}</dd></div><div><dt>Court</dt><dd>${h(r.court||'Not recorded')}</dd></div><div><dt>Participant</dt><dd>${h(r.actors.join(', ')||'Not recorded')}</dd></div><div><dt>AI tool as recorded</dt><dd>${h(r.tool)}</dd></div><div><dt>Monetary entry</dt><dd>${h(money(r))}</dd></div><div><dt>Professional-sanction flag</dt><dd>${r.discipline?'Yes':'No'} · as classified by the source</dd></div><div><dt>U.S. location</dt><dd>${h(C.STATES[r.state]||r.state||'Not assigned')}${r.stateInferred?' (inferred from court label)':''}</dd></div><div class="full"><dt>Outcome as recorded</dt><dd>${h(r.outcome||'Not recorded')}</dd></div></dl>${r.disputed?`<div class="callout warn"><h3>Vendor dispute recorded</h3><p>${h(r.disputeNote||'The source marks this record as disputed but supplies no explanation in this field.')}</p></div>`:''}${r.alleged?'<div class="callout warn"><p>The source flags the AI use as alleged. Do not treat this record as a confirmed finding of AI use.</p></div>':''}<h3>Source description of the error</h3>${items.length?items.map(x=>`<p class="detail-text">${h(x)}</p>`).join(''):'<p class="muted">No error description supplied in this field.</p>'}${r.details?`<h3>Additional source notes</h3><p class="detail-text">${h(r.details)}</p>`:''}${r.pointer?`<p><strong>Source pinpoint:</strong> ${h(r.pointer)}</p>`:''}<p class="chart-note">This description comes from the active dataset and has not been independently verified. Read the source before relying on it. A blank outcome is not a finding that no sanction occurred.</p>`;}
function showCase(id){const r=records.find(x=>x.id===id);if(!r)return;modal(r.title,caseDetail(r),`${r.source?`<a class="button primary" href="${h(r.source)}" target="_blank" rel="noopener noreferrer">Read the source document ↗</a>`:'<span>No source URL recorded.</span>'}<button data-action="case-export" data-id="${r.id}">Export record</button>`,true);}
function exportCSV(rows){const cols=['Decision','Court','Jurisdiction','Date','Participants','AI tool','Error types','Error description','Outcome','Monetary entry (original)','Known amount','Currency','Amount status','Professional-sanction flag','AI use alleged','Vendor disputed','Vendor dispute explanation','Source URL','Details','Data author','Snapshot'];download('decisions-filtered.csv',C.toCSV([cols,...rows.map(r=>[r.title,r.court,r.countries.join('; '),r.date,r.actors.join('; '),r.tool,r.types.join('; '),r.items,r.outcome,r.money.raw,r.money.value??'',r.money.currency,r.money.status,r.discipline?'Yes':'No',r.alleged?'Yes':'No',r.disputed?'Yes':'No',r.disputeNote,r.source,r.details,dataset.meta.author,dataset.meta.snapshot])]),'text/csv;charset=utf-8');}
function selectedSource(rows){const indices=rows.map(r=>Number(r.id.slice(1))-1);return {...dataset,rows:indices.map(i=>dataset.rows[i])};}
function projectExport(){download('research-project.json',JSON.stringify({dataset,config,mapping},null,2),'application/json');}
function portable(){const clone=document.documentElement.cloneNode(true);clone.querySelector('#dataset').textContent=JSON.stringify(dataset).replace(/</g,'\\u003c');clone.querySelector('#project-config').textContent=JSON.stringify({...config,embeddedMapping:mapping,exportId:Date.now().toString(36)}).replace(/</g,'\\u003c');clone.querySelector('#main').innerHTML='<p>Preparing the records…</p>';clone.querySelector('#sidebar').innerHTML='';clone.querySelector('#topbar').innerHTML='';clone.querySelector('#footer').innerHTML='';clone.querySelector('#modal-root').innerHTML='';clone.querySelector('#toast').hidden=true;clone.querySelector('body').className='';clone.querySelector('body').style.overflow='';clone.querySelectorAll('.tooltip').forEach(x=>x.remove());download('research-explorer.html','<!doctype html>\n'+clone.outerHTML,'text/html;charset=utf-8');toast('The portable file includes your dataset and project settings.');}
function markdownExercises(){let text='# Reviewing AI-assisted legal work\n\nOriginal fictional exercises for Write.law. No source passages are real authorities.\n\n## Facilitator notes\n\nAsk participants to read the source before evaluating the draft. Have them explain what needs attention and what information they still need. Discuss competing revisions before revealing the answer. The suggested repairs illustrate writing decisions; they are not complete legal advice or jurisdiction-specific templates.\n\n';for(const e of T.exercises)text+=`## ${e.group}: ${e.title}\n\n### Source or instructions\n${e.source}\n\n### Draft\n${e.draft}\n\n${e.question}\n\n${e.choices.map((c,i)=>`${i+1}. ${c}`).join('\n')}\n\n`;text+='\n# Answer key and discussion\n\n';for(const e of T.exercises)text+=`## ${e.title}\n\nSuggested choice: ${e.correct+1}. ${e.choices[e.correct]}\n\n${e.explanation}\n\nPossible repair or next step: ${e.repair}\n\nDiscussion: ${e.discussion}\n\n`;return text;}
async function importFile(file){if(!file)return;if(file.size>25*1024*1024){toast('Please use a file smaller than 25 MB.');return;}try{const text=await file.text();let data,suppliedMapping=null,suppliedConfig=null;if(/\.csv$/i.test(file.name))data=C.parseCSV(text);else {const j=JSON.parse(text);if(j.dataset){data=j.dataset;suppliedMapping=j.mapping;suppliedConfig=j.config;}else data=Array.isArray(j)?{rows:j}:j;}if(!data||!Array.isArray(data.rows)||!data.rows.length||data.rows.length>50000)throw Error('Use a nonempty array of up to 50,000 records.');const cols=data.columns||Object.keys(data.rows[0]);if(!cols.length||data.rows.some(r=>!r||typeof r!=='object'))throw Error('Each row must contain a record.');const aliases={title:['title','decision','case','name'],date:['date','decision date'],countries:['country','jurisdiction'],actors:['participants','actor'],tool:['tool','product'],items:['errors','error','error type'],outcome:['outcome','result'],money:['amount','monetary penalty'],details:['details','description'],source:['source url','url'],court:['court','organization'],state:['us state','state']};const map={};Object.entries(C.DEFAULT_MAPPING).forEach(([k,v])=>{map[k]=cols.includes(v)?v:cols.find(c=>[k,...(aliases[k]||[])].includes(c.toLowerCase()))||'';});ui.pending={dataset:data,mapping:suppliedMapping||map,config:suppliedConfig,filename:file.name};render();document.querySelector('#import-form')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast('Import not applied: '+e.message);}}
function applyImport(form){const f=new FormData(form),p=ui.pending,map={};Object.keys(C.DEFAULT_MAPPING).forEach(k=>map[k]=String(f.get('map-'+k)||''));if(!map.title){toast('Map a record-title column before importing.');return;}const source=String(f.get('source')||'');const meta={...(p.dataset.meta||{}),name:String(f.get('datasetName')||p.filename),author:String(f.get('author')||'Not specified'),source:source?C.safeURL(source):'',sourceBase:source?C.safeURL(source):''||'https://example.invalid/',snapshot:C.validDate(f.get('snapshot')),license:String(f.get('license')||'Not specified'),oneIsUnknown:f.get('sentinel')==='on',custom:true,note:'Locally imported dataset. Source records have not been independently verified.'};const next={...p.dataset,meta};try{const normalized=C.normalizeDataset(next,map);dataset=next;mapping=map;records=normalized;ui.pending=null;ui.selected=[];ui.saved=[];ui.f={};ui.onlySaved=false;ui.page=1;config=p.config?{...config,...p.config}:{...config,name:meta.name,intro:'Explore the records in this dataset. Use the filters to compare groups, read individual entries, and trace each entry to its source.',study:false,practice:false};go('overview');const bad=records.filter(r=>r.dateRaw&&!r.date).length;toast(`${n(records.length)} records imported locally.${bad?' '+n(bad)+' invalid dates excluded from time charts.':''} Export a copy to keep them.`);}catch(e){toast('Import not applied: '+e.message);}}
const handlers={
'jump-finding':b=>{if(ui.route!=='overview'){ui.route='overview';render();}ui.findingSection=b.dataset.target;syncHash();scrollToFinding(b.dataset.target);},
'finding-cases':b=>{try{ui.f=JSON.parse(b.dataset.filters);ui.onlySaved=false;go('decisions');}catch{toast('That selection could not be opened.');}},
'findings-print':()=>window.print(),
'findings-export':findingsExport,

'go':b=>go(b.dataset.route),'menu':()=>{document.body.classList.toggle('menu-open');$('topbar').querySelector('[data-action="menu"]').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')));},
'reset':()=>{ui.f={};ui.onlySaved=false;ui.page=1;syncHash();render();},'remove-filter':b=>setFilter(b.dataset.key,''),
'bar-filter':b=>{setFilter(b.dataset.key,b.dataset.value,'decisions');window.scrollTo(0,0);},
'map-state':b=>{ui.f.country='USA';setFilter('state',b.dataset.value,'decisions');window.scrollTo(0,0);},
'month-filter':b=>{if(ui.route==='overview'){ui.f={};ui.onlySaved=false;}const m=b.dataset.month;ui.f.from=ui.cumulative?'':m+'-01';const d=new Date(m+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(0);ui.f.to=d.toISOString().slice(0,10);go('decisions');},
'chart-export':()=>{const svg=$('timeline-svg').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.querySelectorAll('[data-action]').forEach(x=>{x.removeAttribute('data-action');x.removeAttribute('tabindex');x.removeAttribute('role');});let text=svg.outerHTML;const css=getComputedStyle(document.documentElement);['accent','line','muted','ink'].forEach(k=>text=text.replaceAll('var(--'+k+')',css.getPropertyValue('--'+k).trim()));download('decisions-timeline.svg',text,'image/svg+xml');},'chart-data':()=>download('decisions-by-month.csv',C.toCSV([['Month','Decisions','Cumulative','Source author','Snapshot'],...C.series(ui.route==='overview'?records:filtered()).map(d=>[d.month,d.count,d.total,dataset.meta.author,dataset.meta.snapshot])]),'text/csv;charset=utf-8'),
 'timeline':b=>{ui.cumulative=b.dataset.mode==='total';render();},'view':()=>{ui.table=!ui.table;render();},'page':b=>{ui.page+=Number(b.dataset.delta);render();document.querySelector('.toolbar')?.scrollIntoView({block:'start'});},
'case':b=>showCase(b.dataset.id),'save':b=>{const id=b.dataset.id;ui.saved=ui.saved.includes(id)?ui.saved.filter(x=>x!==id):[...ui.saved,id];if(!dataset.meta.custom)store(':saved',ui.saved);render();},
'clear-compare':()=>{ui.selected=[];render();},'compare':()=>{const chosen=ui.selected.map(id=>records.find(r=>r.id===id)).filter(Boolean);modal('Compare decisions',`<div class="grid2 equal">${chosen.map(r=>`<article><h3>${h(r.title)}</h3>${caseDetail(r)}${r.source?`<a href="${h(r.source)}" target="_blank" rel="noopener noreferrer">Read source ↗</a>`:''}</article>`).join('')}</div>`,'',true);},
'close-modal':closeModal,'case-export':b=>{const r=records.find(x=>x.id===b.dataset.id);if(r)download('decision-record.json',JSON.stringify({record:r,provenance:dataset.meta},null,2),'application/json');},
'export-csv':()=>exportCSV(currentRows()),'export-json':()=>download('decisions-filtered.json',JSON.stringify({dataset:selectedSource(currentRows()),mapping,config},null,2),'application/json'),
'practice-group':b=>{ui.group=b.dataset.group;ui.exercise=T.exercises.find(x=>x.group===ui.group).id;render();},'exercise':b=>{ui.exercise=b.dataset.id;render();},
'reveal':b=>{const checked=document.querySelector('[name="exercise-answer"]:checked');if(!checked){toast('Choose a response before opening the explanation.');return;}ui.practice[b.dataset.id]={choice:Number(checked.value),revealed:true};store(':practice',ui.practice);render();document.querySelector('.answer')?.scrollIntoView({behavior:'smooth',block:'nearest'});},
'practice-export':()=>download('practice-exercises-and-answer-key.md',markdownExercises()),'practice-reset':()=>{modal('Reset exercise progress?','<p>This removes the saved choices and completion marks in this browser.</p>','<button data-action="close-modal">Keep progress</button><button data-action="practice-reset-confirm">Reset progress</button>');},'practice-reset-confirm':()=>{ui.practice={};store(':practice',{});closeModal();render();},
'quote-example':()=>{ui.quoteA='The inspection may support an inference of knowledge, but it does not compel that inference.';ui.quoteB='The inspection compels an inference of knowledge.';ui.quoteResult=null;render();},'quote-clear':()=>{ui.quoteA='';ui.quoteB='';ui.quoteResult=null;render();},
'quote-compare':()=>{ui.quoteA=$('quote-a').value;ui.quoteB=$('quote-b').value;ui.quoteNorm=$('quote-normalize').checked;if(!ui.quoteA.trim()||!ui.quoteB.trim()){toast('Paste text into both fields first.');return;}try{ui.quoteResult=C.compareText(ui.quoteA,ui.quoteB,ui.quoteNorm);$('quote-results').innerHTML=quoteOutput();}catch(e){toast(e.message);}},
'review-export':()=>{const text=`# ${ui.reviewGroup} review record\n\nExported ${new Date().toISOString()}\nReviewer / matter: ${ui.reviewer||'Not supplied'}\n\n`+T.checklists[ui.reviewGroup].map(([l,t],i)=>`- [${ui.review[ui.reviewGroup+':'+i]?'x':' '}] ${l}: ${t}`).join('\n')+'\n\nCompletion marks record the user’s choices. They are not a certification of correctness.\n';download('review-record.md',text);},
'review-clear':()=>{T.checklists[ui.reviewGroup].forEach((_,i)=>delete ui.review[ui.reviewGroup+':'+i]);render();},'evidence-add':()=>{ui.evidence.push({claim:'',source:'',status:'Needs review'});render();},'evidence-remove':b=>{ui.evidence.splice(Number(b.dataset.index),1);render();},'evidence-export':()=>download('review-questions.csv',C.toCSV([['Claim or question','Source or location','Review status'],...ui.evidence.map(e=>[e.claim,e.source,e.status])]),'text/csv;charset=utf-8'),
'settings-reset':()=>{config={...BASE};store(':config',config);render();toast('Default project settings restored.');},'cancel-import':()=>{ui.pending=null;render();},'restore-source':()=>{modal('Restore the included snapshot?','<p>This replaces the active dataset and clears current filters and selections. Export an imported dataset before restoring it if you need to keep that data.</p>','<button data-action="close-modal">Keep current dataset</button><button data-action="restore-confirm">Restore snapshot</button>');},'restore-confirm':()=>{dataset=ORIGINAL;mapping=BASE.embeddedMapping||C.DEFAULT_MAPPING;records=C.normalizeDataset(dataset,mapping);ui.saved=readStore(':saved',[]);ui.selected=[];ui.f={};ui.pending=null;ui.onlySaved=false;config={...BASE};store(':config',config);closeModal();go('overview');},
'portable':portable,'project-export':projectExport,'raw-export':()=>{const raw=C.rowsFrom(dataset),cols=dataset.columns||Object.keys(raw[0]||{});download('source-records.csv',C.toCSV([cols,...raw.map(r=>cols.map(c=>r[c]))]),'text/csv;charset=utf-8');download('source-attribution.txt',`${dataset.meta.name}\nCompiled by: ${dataset.meta.author}\n${dataset.meta.source||''}\nReuse terms: ${dataset.meta.license}\nSnapshot: ${dataset.meta.snapshot||'not specified'}\n\nExported by an independent Write.law explorer. CSV export protects spreadsheet readers by prefixing formula-like fields with an apostrophe. Project JSON preserves exact source values.\n`);},
'presentation':()=>{document.body.classList.add('presentation');toast('Presentation view is on. Press Escape to leave.');},
'search':()=>{go('decisions');$('case-search')?.focus();},
'share':async()=>{syncHash();const url=location.href;if(location.protocol==='file:'){toast('This is a local file. Export a portable copy to share it.');return;}if(dataset.meta.custom){toast('This dataset exists only in your browser. Export the portable website to share it.');return;}try{await navigator.clipboard.writeText(url);toast('View link copied, including the current filters.');}catch{modal('Copy this view link',`<label>Link<input id="share-link" readonly value="${h(url)}"></label><p class="formhelp">This link preserves filters, not private notes or saved cases.</p>`);$('share-link').select();}}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&handlers[b.dataset.action]){e.preventDefault();handlers[b.dataset.action](b);}const a=e.target.closest('a[href^="#"]');if(a&&a.getAttribute('href')!=='#main'){e.preventDefault();document.body.classList.remove('menu-open');go(a.hash.slice(1).split('?')[0]);}if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){setFilter(el.dataset.filter,el.type==='checkbox'?el.checked:el.value);return;}if(el.dataset.compare){if(el.checked&&ui.selected.length>=2){el.checked=false;toast('Compare two decisions at a time.');return;}ui.selected=el.checked?[...ui.selected,el.dataset.compare]:ui.selected.filter(x=>x!==el.dataset.compare);render();return;}if(el.dataset.review!==undefined){ui.review[ui.reviewGroup+':'+el.dataset.review]=el.checked;render();return;}if(el.dataset.evidence!==undefined){ui.evidence[Number(el.dataset.evidence)][el.dataset.field]=el.value;return;}if(el.id==='only-saved'){ui.onlySaved=el.checked;ui.page=1;render();}if(el.id==='sort-records'){ui.sort=el.value;render();}if(el.id==='currency'){ui.currency=el.value;render();}if(el.id==='review-group'){ui.reviewGroup=el.value;render();}if(el.id==='quote-normalize'){ui.quoteNorm=el.checked;ui.quoteResult=null;$('quote-results').innerHTML='';}if(el.id==='import-file')importFile(el.files[0]);});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='case-search'){clearTimeout(renderTimer);renderTimer=setTimeout(()=>setFilter('q',el.value),230);}if(el.id==='quote-a'){ui.quoteA=el.value;ui.quoteResult=null;$('quote-results').innerHTML='';}if(el.id==='quote-b'){ui.quoteB=el.value;ui.quoteResult=null;$('quote-results').innerHTML='';}if(el.id==='reviewer')ui.reviewer=el.value;if(el.dataset.evidence!==undefined)ui.evidence[Number(el.dataset.evidence)][el.dataset.field]=el.value;});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();const f=new FormData(e.target);config={...config,name:String(f.get('name')).trim()||BASE.name,organization:String(f.get('organization')).trim(),intro:String(f.get('intro')),accent:String(f.get('accent')),theme:String(f.get('theme')),study:f.get('study')==='on',practice:f.get('practice')==='on'};store(':config',config);render();toast('Settings saved in this browser.');}if(e.target.id==='import-form'){e.preventDefault();applyImport(e.target);}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();handlers.search();}if(e.key==='Escape'){closeModal();document.body.classList.remove('presentation','menu-open');}if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('chart-mark')){e.preventDefault();handlers['month-filter'](e.target);}if(e.key==='Tab'&&$('modal-root').children.length){const nodes=[...$('modal-root').querySelectorAll('a[href],button:not([disabled]),input,select,textarea,[tabindex="0"]')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{fromHash();window.scrollTo(0,0);});
window.App={presentation:v=>document.body.classList.toggle('presentation',v),getData:()=>({total:records.length,filtered:filtered().length,meta:dataset.meta}),getState:()=>({route:ui.route,filters:{...ui.f}})};
if(BASE.embeddedMapping){mapping=BASE.embeddedMapping;records=C.normalizeDataset(dataset,mapping);}
fromHash();
})();
